import numpy as np


def split_photos(shelf_ids, val_share, rng):
    shelves = rng.permutation(np.unique(shelf_ids))
    n_val = round(len(shelves) * val_share)
    in_val = np.isin(shelf_ids, shelves[:n_val])
    return np.flatnonzero(~in_val), np.flatnonzero(in_val)
